function voiceGlyph(name){const paths={people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87',share:'M12 16V3m-5 5 5-5 5 5M5 12H3v9h18v-9h-2',more:'M5 12h.01M12 12h.01M19 12h.01',megaphone:'M3 10h5l10-5v14L8 14H3zM6 14l2 7h3l-2-7M21 9v6',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18',lock:'M6 10V7a6 6 0 0 1 12 0v3M4 10h16v12H4zM12 14v4',person:'M20 21v-2a6 6 0 0 0-6-6h-4a6 6 0 0 0-6 6v2M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',wave:'M3 10v4M7 6v12M12 2v20M17 7v10M21 10v4',trash:'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',ban:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM6 6l12 12',repeat:'M3 8h15l-4-4M21 16H6l4 4M18 8a5 5 0 0 1 3 5M6 16a5 5 0 0 1-3-5',previous:'M6 5v14M19 5 8 12l11 7z',next:'M18 5v14M5 5l11 7-11 7z',smile:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM8 14s1 3 4 3 4-3 4-3M8 8h.01M16 8h.01',playlist:'M3 5h13M3 10h13M3 15h8M19 10v9m0-9 3-1M19 19a2 2 0 1 1-4 0 2 2 0 0 1 4 0',home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',crown:'M3 7l4 4 5-8 5 8 4-4-2 13H5z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',leave:'M9 3H3v18h6m5-14 5 5-5 5M7 12h12',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M18 6 6 18',muted:'m3 3 18 18M9 9v3a3 3 0 0 0 5 2M15 9V5a3 3 0 0 0-6 0M5 11v1a7 7 0 0 0 12 5M19 11v1M12 19v3m-4 0h8'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${name==='people'?'<circle cx="9" cy="7" r="4"/>':''}<path d="${paths[name]||paths.plus}"/></svg>`;}
function voiceRoomHTML(id){
 const close='<button type="button" class="voice-dialog-close" data-voice="dismiss" aria-label="닫기">'+voiceGlyph('close')+'</button>';
 return `<section class="voice-room" data-voice-room="${esc(id)}"><header class="voice-heading"><a href="#voice">← 토킹룸</a><div class="voice-stage-toolbar"><p>좌석을 눌러 참여 신청해보세요.</p><div><button type="button" class="voice-icon-button" data-voice="participants" aria-label="참가자 목록">${voiceGlyph('people')}<span id="voice-people-count"></span></button><button type="button" class="voice-icon-button" data-voice="sound" aria-label="소리 설정">${icon('mic')}</button><button type="button" class="voice-icon-button" data-voice="settings" aria-label="방 설정">${voiceGlyph('home')}</button><button type="button" class="voice-icon-button" data-voice="share" aria-label="초대하기">${voiceGlyph('share')}</button><button class="small-button voice-leave" data-voice="leave">나가기</button></div></div><h1 id="voice-title">토킹룸</h1><p><span id="voice-count"></span><span id="voice-status" role="status">연결하는 중…</span></p></header><div id="voice-entry" hidden><button id="voice-join" class="primary-button">다시 연결</button></div><div id="voice-content" hidden><div class="voice-columns"><section class="voice-stage"><div id="voice-music-player" class="voice-music-mini" aria-label="공동 음악"></div><div id="voice-seats" class="voice-seats"></div><button class="small-button voice-unlock-audio" data-voice="resume-audio" hidden>소리 켜기</button><button class="small-button voice-cancel-request" data-voice="cancel-mic" hidden>신청 취소</button><p id="voice-mic-note" class="quiet"></p><div id="voice-listeners" class="voice-listeners"></div></section><section class="voice-chat-panel"><aside id="voice-announcement" class="voice-announcement" hidden><span class="voice-notice-icon">${voiceGlyph('megaphone')}</span><div><strong>방 공지</strong><p id="voice-announcement-text"></p></div></aside><div id="voice-seat-invitation" role="status" hidden></div><div id="voice-chat" class="voice-chat" aria-live="polite" aria-relevant="additions"></div><form id="voice-chat-form"><label class="sr-only" for="voice-message">메시지</label><textarea id="voice-message" name="body" placeholder="메시지를 입력하세요…" maxlength="500" required rows="1" enterkeyhint="send" aria-describedby="voice-chat-help"></textarea><span id="voice-chat-help" class="sr-only">Enter로 전송, Shift+Enter로 줄바꿈. 이모티콘 메뉴에서도 메시지를 보낼 수 있어요.</span><button type="button" class="voice-icon-button" data-voice="emoji" aria-label="이모티콘">${voiceGlyph('smile')}</button><button type="button" class="voice-icon-button" data-voice="gift" aria-label="선물 보내기">${icon('gift')}</button></form></section></div><div id="voice-gift-animation" class="voice-gift-animation" role="status" hidden></div>
 <dialog id="voice-sound" class="voice-sheet">${close}<header class="voice-sheet-heading"><span>${icon('mic')}</span><div><h2>소리 설정</h2><p>방송과 음성 대화에 사용할 마이크와 소리를 설정하세요.</p></div></header><p id="voice-sound-current" class="quiet voice-current-song"></p>
 <section class="voice-audio-card"><h3>${icon('mic')} 마이크 입력 볼륨 <output data-value-for="voice-input-gain">100%</output></h3><label class="voice-range-row">${icon('volume')}<input id="voice-input-gain" aria-label="내 마이크 음량" type="range" min="0" max="100" value="100">${icon('volume')}</label></section>
 <section class="voice-audio-card voice-toggle-card"><div><h3>${icon('headphones')} 내 목소리 모니터링</h3><p>내 목소리를 실시간으로 들을 수 있어요. 이어폰 사용을 권장해요.</p></div><label class="voice-switch"><input id="voice-monitor" type="checkbox" aria-label="내 목소리 모니터링"><span></span></label></section>
 <section class="voice-audio-card voice-toggle-card"><div><h3>${voiceGlyph('wave')} 노이즈 제거</h3><p>주변 소음을 줄여 내 목소리를 더 또렷하게 전달해요.</p></div><label class="voice-switch"><input id="voice-noise" type="checkbox" checked aria-label="노이즈 제거"><span></span></label></section>
 <section class="voice-audio-card voice-toggle-card"><div><h3>${voiceGlyph('wave')} 에코 제거</h3><p>스피커 소리가 마이크에 다시 들어오는 것을 줄여요.</p></div><label class="voice-switch"><input id="voice-echo" type="checkbox" checked aria-label="에코 제거"><span></span></label></section>
 <section class="voice-audio-card voice-effect-card"><div><h3>${icon('sliders')} 에코 / 리버브 효과</h3><p>목소리에 은은한 공간감을 더해보세요.</p></div><label><span class="sr-only">마이크 음질</span><select id="voice-preset"><option value="original">원음 · 효과 끔</option><option value="radio" selected>라디오 클린 · 기본</option><option value="studio">스튜디오 · 은은하게</option></select></label><label class="voice-reverb-row">리버브 강도 <input id="voice-reverb" type="range" min="0" max="7" value="0"></label></section>
 <section id="voice-host-audio" class="voice-audio-card"><h3>${voiceGlyph('playlist')} 공유 음악 볼륨 <output data-value-for="voice-room-volume">70%</output></h3><p>방에서 함께 듣는 음악의 기준 볼륨을 조절해요.</p><label class="voice-range-row">${icon('volume')}<input id="voice-room-volume" aria-label="방 전체 음악 볼륨" type="range" min="0" max="100" step="1">${icon('volume')}</label><details><summary>음악과 목소리 균형</summary><label>목소리 중심 ↔ 음악 중심 <input id="voice-balance" type="range" min="0" max="100" step="1"></label><button class="small-button" data-voice="music-picker">플레이리스트 열기</button></details></section>
 <section class="voice-audio-card voice-mic-test"><h3>${voiceGlyph('wave')} 마이크 테스트</h3><p>마이크에 대고 말해보세요. 입력되는 목소리가 실시간으로 표시돼요.</p><div class="voice-test-controls"><meter id="voice-input-meter" min="0" max="1" value="0" aria-label="실제 마이크 입력 레벨"></meter><button type="button" class="small-button" data-voice="mic-test">${icon('mic')} 테스트 시작</button></div></section>
 <details class="voice-audio-extra"><summary>입력 장치 · 개인 청취 볼륨 · 연결 진단</summary><label>내 마이크 입력 장치<select id="voice-input"><option value="">기본 마이크</option></select></label><label>출력 장치<select id="voice-output"><option value="">기본 스피커 / 이어폰</option></select></label><label>개인 음악 볼륨 <input id="voice-music-volume" type="range" min="0" max="100" value="100"></label><label>참가자 목소리 <input id="voice-listen-volume" type="range" min="0" max="100" value="100"></label><p id="voice-diagnostics-summary" class="quiet">음성 연결 후 측정할 수 있어요.</p><button class="small-button" data-voice="diagnostics-export">통계 내려받기</button><p class="quiet">장치가 지원하지 않는 효과는 원음으로 연결돼요.</p></details></dialog>
 <dialog id="voice-members" class="voice-sheet" aria-labelledby="voice-members-count">${close}<header class="voice-members-header">${voiceGlyph('people')}<h2 id="voice-members-count">참여자</h2></header><p id="voice-host-hint" class="voice-host-hint" hidden>${voiceGlyph('crown')}<strong>방장 전용 관리 메뉴</strong><span>참여자의 더보기 메뉴를 통해 관리할 수 있습니다.</span></p><div id="voice-members-list"></div><div id="voice-member-tools" hidden></div><section id="voice-requests"></section></dialog>
 <dialog id="voice-room-settings" class="voice-sheet">${close}<header class="voice-sheet-heading"><span>${voiceGlyph('home')}</span><h2>방 설정</h2></header><form id="voice-settings-form"><label>방 제목<input name="title" maxlength="60" required></label><fieldset><legend>방 공개 설정</legend><div class="voice-visibility"><label><input type="radio" name="visibility" value="public">${voiceGlyph('globe')}<strong>공개방</strong><small>누구나 참여 가능</small></label><label><input type="radio" name="visibility" value="private">${voiceGlyph('lock')}<strong>비공개방</strong><small>초대된 사람만</small></label><label><input type="radio" name="visibility" value="crew">${voiceGlyph('people')}<strong>크루만</strong><small>내 크루만 참여 가능</small></label><label><input type="radio" name="visibility" value="followers">${voiceGlyph('person')}<strong>팔로우만</strong><small>내 팔로워만 참여 가능</small></label></div></fieldset><label class="voice-crew-setting">연결할 크루<select name="crew_id" id="voice-settings-crew"><option value="">크루 선택</option></select></label><label>최대 참여 인원<select name="max_members"><option value="2">2명</option><option value="3">3명</option><option value="4">4명</option><option value="5">5명</option><option value="6">6명</option><option value="7">7명</option><option value="8">8명</option><option value="9">9명</option><option value="10">10명</option><option value="11">11명</option><option value="12">12명</option><option value="13">13명</option><option value="14">14명</option><option value="15">15명</option><option value="16">16명</option><option value="17">17명</option><option value="18">18명</option><option value="19">19명</option><option value="20">20명</option><option value="21">21명</option><option value="22">22명</option><option value="23">23명</option><option value="24">24명</option><option value="25">25명</option><option value="26">26명</option><option value="27">27명</option><option value="28">28명</option><option value="29">29명</option><option value="30">30명</option></select></label><fieldset><legend>방 배경</legend><div class="voice-backgrounds"><label data-background="navy"><input type="radio" name="background" value="navy"><span>차분한 다크</span></label><label data-background="sunset"><input type="radio" name="background" value="sunset"><span>차분한 노을</span></label><label data-background="night"><input type="radio" name="background" value="night"><span>밤하늘</span></label></div></fieldset><label>방 공지<span class="voice-notice-input"><textarea name="announcement" maxlength="200" rows="3"></textarea><output id="voice-notice-length">0/200</output></span></label><button class="primary-button voice-settings-save">저장하기</button></form><p id="voice-settings-readonly" class="quiet" hidden>방장이 설정을 변경할 수 있어요.</p><button class="small-button" data-voice="close" hidden>토킹룸 종료</button></dialog>
 <dialog id="voice-music-sheet" class="voice-sheet">${close}<header class="voice-sheet-heading voice-playlist-heading"><h2>플레이리스트</h2></header><form id="voice-music-search"><label class="sr-only" for="voice-music-query">곡명 · 아티스트</label>${icon('search')}<input id="voice-music-query" placeholder="노래 제목이나 아티스트를 검색해보세요." maxlength="100"><button class="small-button" aria-label="음악 검색">검색</button></form><p class="quiet voice-music-rights">권리자가 공동 감상을 허용한 원곡만 재생할 수 있어요.</p><header id="voice-results-heading" class="voice-results-heading" hidden><h3>검색 결과</h3><small id="voice-search-count"></small></header><div id="voice-music-results"></div><section id="voice-playlist-empty" class="voice-playlist-empty"><span>♫</span><h3>아직 추가된 음악이 없어요</h3><p>위 검색창에서 노래를 찾아 + 버튼으로 추가해 주세요.</p><small>추가된 음악이 있으면 이곳에 재생목록이 나타납니다.</small></section><section id="voice-queue-area" hidden><header class="voice-queue-heading"><h3>내 플레이리스트 <small id="voice-queue-count"></small></h3><button type="button" data-voice="music-clear">${voiceGlyph('trash')} 전체 삭제</button></header><div class="voice-popup-player"><div id="voice-popup-current"></div><div class="voice-music-transport"><button data-voice="music-previous" aria-label="이전 곡">${voiceGlyph('previous')}</button><button data-voice="music-play" aria-label="음악 재생">${icon('play')}</button><button data-voice="music-pause" aria-label="음악 일시정지">${icon('pause')}</button><button data-voice="music-next" aria-label="다음 곡">${voiceGlyph('next')}</button><button data-voice="music-repeat">반복 끔</button><button data-voice="music-stop">종료</button><label>재생 위치 <input id="voice-music-seek" type="range" min="0" max="0" value="0" step="1"></label></div><div id="voice-playlist-personal"><label>개인 음악 볼륨<input id="voice-playlist-volume" type="range" min="0" max="100" value="100"></label></div></div><h3 id="voice-queue-heading" hidden>재생목록</h3><div id="voice-music-queue"></div></section></dialog>
 <dialog id="voice-emoji-sheet" class="voice-sheet">${close}<h2>이모티콘</h2><div class="voice-emojis"><button type="button" data-voice="insert-emoji" data-target="😀">😀</button><button type="button" data-voice="insert-emoji" data-target="😊">😊</button><button type="button" data-voice="insert-emoji" data-target="💜">💜</button><button type="button" data-voice="insert-emoji" data-target="👏">👏</button><button type="button" data-voice="insert-emoji" data-target="🎵">🎵</button><button type="button" data-voice="insert-emoji" data-target="✨">✨</button><button type="button" data-voice="insert-emoji" data-target="👍">👍</button><button type="button" data-voice="insert-emoji" data-target="🥰">🥰</button><button type="button" data-voice="insert-emoji" data-target="😂">😂</button><button type="button" data-voice="insert-emoji" data-target="🎉">🎉</button><button type="button" data-voice="insert-emoji" data-target="🌙">🌙</button><button type="button" data-voice="insert-emoji" data-target="🙌">🙌</button></div><button class="small-button" data-voice="send-chat">메시지 보내기</button></dialog><dialog id="voice-seat-picker" class="voice-sheet">${close}<h2>좌석 초대</h2><div id="voice-seat-candidates"></div></dialog><dialog id="voice-kick-confirm" class="voice-sheet">${close}<h2>참여자를 내보낼까요?</h2><p>방에서 나가며 기존 정책에 따라 1분 동안 재입장할 수 없어요.</p><button class="primary-button" data-voice="confirm-kick">강퇴</button></dialog><dialog id="voice-invite-sheet" class="voice-sheet">${close}<h2>초대하기</h2><button class="small-button" data-voice="copy-link">초대 링크 복사</button><form id="voice-invite-form"><label>대화한 친구 <select name="profile_id" required id="voice-contacts"><option value="">친구 선택</option></select></label><button class="small-button">초대 DM 보내기</button><p class="quiet">비공개방 초대는 방장·관리자만 보낼 수 있어요.</p></form></dialog>
 <dialog id="voice-gift-sheet" class="voice-sheet">${close}<h2>선물 보내기</h2><form id="voice-gift-form"><label>받는 사람 <select name="profile_id" required id="voice-gift-target"></select></label><label>선물 <select name="gift_type">${AifectGifts.GIFT_CATALOG.map(g=>`<option value="${esc(g.id)}">${esc(g.name)} · ${number(g.gold)} G</option>`).join('')}</select></label><label>수량 <input name="quantity" type="number" min="1" max="100" value="1" required></label><p id="voice-gift-summary"></p><button class="primary-button">골드 선물 보내기</button><p class="quiet">기존 프로필 선물 정산 기준이 적용돼요.</p><p id="voice-gift-result" role="status"></p></form></dialog></div></section>`;
}
